CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY, sku TEXT NOT NULL UNIQUE, barcode TEXT NOT NULL UNIQUE, name TEXT NOT NULL, category TEXT NOT NULL DEFAULT '', unit TEXT NOT NULL DEFAULT 'عدد', price NUMERIC(18,2) NOT NULL DEFAULT 0, reorder_point INTEGER NOT NULL DEFAULT 0, safety_stock INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS warehouses (id TEXT PRIMARY KEY, name TEXT NOT NULL, city TEXT NOT NULL DEFAULT '', capacity INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS branches (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, city TEXT NOT NULL DEFAULT '', active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE warehouses ADD COLUMN IF NOT EXISTS branch_id TEXT REFERENCES branches(id);
CREATE TABLE IF NOT EXISTS organization_settings (id INTEGER PRIMARY KEY DEFAULT 1 CHECK(id = 1), legal_name TEXT NOT NULL DEFAULT '', registration_number TEXT NOT NULL DEFAULT '', default_currency TEXT NOT NULL DEFAULT 'IRR', tax_id TEXT NOT NULL DEFAULT '', active BOOLEAN NOT NULL DEFAULT true, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS locations (id TEXT PRIMARY KEY, warehouse_id TEXT NOT NULL REFERENCES warehouses(id), code TEXT NOT NULL UNIQUE, hall TEXT NOT NULL DEFAULT '', aisle TEXT NOT NULL DEFAULT '', rack TEXT NOT NULL DEFAULT '', bin TEXT NOT NULL DEFAULT '', capacity INTEGER NOT NULL DEFAULT 0, occupied INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'فعال');
CREATE TABLE IF NOT EXISTS inventory (id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES products(id), warehouse_id TEXT NOT NULL REFERENCES warehouses(id), location_id TEXT NOT NULL REFERENCES locations(id), quantity INTEGER NOT NULL DEFAULT 0 CHECK(quantity >= 0), reserved INTEGER NOT NULL DEFAULT 0 CHECK(reserved >= 0 AND reserved <= quantity), batch TEXT NOT NULL DEFAULT '', expiry DATE, UNIQUE(product_id, warehouse_id, location_id, batch));
CREATE TABLE IF NOT EXISTS movements (id TEXT PRIMARY KEY, number TEXT NOT NULL UNIQUE, type TEXT NOT NULL, product_id TEXT NOT NULL REFERENCES products(id), quantity INTEGER NOT NULL CHECK(quantity > 0), warehouse_id TEXT NOT NULL REFERENCES warehouses(id), location_id TEXT REFERENCES locations(id), batch TEXT NOT NULL DEFAULT '', user_name TEXT NOT NULL DEFAULT 'system', status TEXT NOT NULL DEFAULT 'پیش‌نویس', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS customers (id TEXT PRIMARY KEY, name TEXT NOT NULL, phone TEXT NOT NULL DEFAULT '', national_id TEXT NOT NULL DEFAULT '', city TEXT NOT NULL DEFAULT '', address TEXT NOT NULL DEFAULT '', credit_limit NUMERIC(18,2) NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS drivers (id TEXT PRIMARY KEY, name TEXT NOT NULL, phone TEXT NOT NULL DEFAULT '', national_id TEXT NOT NULL DEFAULT '', license_number TEXT NOT NULL DEFAULT '', active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS vehicles (id TEXT PRIMARY KEY, plate TEXT NOT NULL UNIQUE, type TEXT NOT NULL DEFAULT 'کامیون', capacity INTEGER NOT NULL DEFAULT 0, driver_id TEXT REFERENCES drivers(id), active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY, number TEXT NOT NULL UNIQUE, customer TEXT NOT NULL, destination TEXT NOT NULL DEFAULT '', product TEXT NOT NULL DEFAULT '', quantity INTEGER NOT NULL DEFAULT 0, driver TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'ثبت‌شده', eta TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE orders ADD COLUMN IF NOT EXISTS customer_id TEXT REFERENCES customers(id);
ALTER TABLE orders ADD COLUMN IF NOT EXISTS driver_id TEXT REFERENCES drivers(id);
ALTER TABLE orders ADD COLUMN IF NOT EXISTS vehicle_id TEXT REFERENCES vehicles(id);
ALTER TABLE orders ADD COLUMN IF NOT EXISTS source_warehouse_id TEXT REFERENCES warehouses(id);
ALTER TABLE orders ADD COLUMN IF NOT EXISTS loaded_at TIMESTAMPTZ;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS dispatched_at TIMESTAMPTZ;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS delivered_at TIMESTAMPTZ;
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY, action TEXT NOT NULL, entity TEXT NOT NULL, user_name TEXT NOT NULL, detail TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS invoices (id TEXT PRIMARY KEY, number TEXT NOT NULL UNIQUE, order_id TEXT REFERENCES orders(id), customer TEXT NOT NULL, subtotal NUMERIC(18,2) NOT NULL DEFAULT 0, discount NUMERIC(18,2) NOT NULL DEFAULT 0, tax NUMERIC(18,2) NOT NULL DEFAULT 0, total NUMERIC(18,2) NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'پیش‌نویس', issued_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','warehouse_manager','warehouse_operator','sales','accounting','auditor')), active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE users ADD COLUMN IF NOT EXISTS branch_id TEXT REFERENCES branches(id);
CREATE TABLE IF NOT EXISTS user_warehouses (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, warehouse_id TEXT NOT NULL REFERENCES warehouses(id) ON DELETE CASCADE, PRIMARY KEY(user_id, warehouse_id));
CREATE INDEX IF NOT EXISTS inventory_product_warehouse_idx ON inventory(product_id, warehouse_id);
CREATE INDEX IF NOT EXISTS movements_created_at_idx ON movements(created_at DESC);
CREATE INDEX IF NOT EXISTS audit_created_at_idx ON audit_events(created_at DESC);
CREATE INDEX IF NOT EXISTS warehouses_branch_idx ON warehouses(branch_id);
CREATE INDEX IF NOT EXISTS user_warehouses_warehouse_idx ON user_warehouses(warehouse_id);
